import {
  Component,
  Element,
  Event,
  type EventEmitter,
  Host,
  Prop,
  State,
  h,
} from "@stencil/core";
import { alertsNegativeLarge, alertsPositiveLarge } from "../../../icons";
import { remove } from "../../../icons";
import FormControl from "../../functional-components/form-control/form-control";
import { generateShortID } from "../../utils/function-helper";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { hasSlot } from "../../utils/slot";

/**
 * @since 0.0.14
 * @status stable
 *
 * @slot suffix - suffix of the progress bar, if present, the default suffix will be overwritten
 *
 * @part base - The component's base wrapper.
 * @part percentage - The progress bar percentage.
 * @part label - The progress bar label.
 * @part track - The progress bar track.
 * @part suffix - The progress bar suffix.
 * @part percentage-text - The progress bar suffix-percentage text.
 */

@Component({
  tag: "hbr-progress-bar",
  styleUrl: "progress-bar.scss",
  shadow: true,
})
export class ProgressBar {
  uuid = generateShortID();
  _helpTextId = `progress-bar-helpTextId-${this.uuid}`;
  labelId = `progress-bar-label-${this.uuid}`;

  @Element() host: HTMLHbrProgressBarElement;

  @State() hasFocus = false;
  @State() hasContent = false;
  @State() hasHelpTextSlot = false;
  @State() hasLabelSlot = false;
  @State() hasFrontSlot = false;
  @State() hasRearSlot = false;

  /** The progress bar's percentage, 0 to 100. */
  @Prop({ reflect: true }) percentage = 0;

  /** When true, percentage is ignored, the label is hidden, and the progress bar is drawn in an indeterminate state. */
  @Prop({ reflect: true }) indeterminate = false;

  /** When true, error icon will be shown  */
  @Prop({ reflect: true }) error = false;

  /** When true, suffix will be hidden  */
  @Prop() noSuffix = false;

  /** Set to true to disable the radio. */
  @Prop({ reflect: true }) disabled = false;

  /** Set to true to make the radio a required field. */
  @Prop({ reflect: true }) required = false;

  /** Label size */
  @Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

  /** Magnetic label alignment */
  @Prop({ reflect: true }) alignment:
    | "no-label"
    | "inline"
    | "stacked"
    | "stacked-center" = "stacked";

  /** The label attribute. */
  @Prop({ reflect: true }) label = "";

  /** The help text. */
  @Prop({ reflect: true }) helpText = "";

  /** The help text id. */
  @Prop({ reflect: true }) helpTextId = "";

  /** When true, show suffix  */
  @Prop() indicator = true;

  /** When true, the css transition animation is disabled  */
  @Prop() inanimate = false;

  /** When true, the progress bar will not have a stop (X) icon. since v2.8.0 */

  @Prop() noncancelable = false;

  /** Attributes related to screen readers. */
  @Prop() aria: { label?: string; labelledby?: string };

  /** this event will be fire when clicking on the X icon when hovering on the suffix, except success and error  */
  @Event({ eventName: "hbr-stop" }) hbrStop: EventEmitter;

  renderIndicator() {
    const customSystemIcons = getBootstrapConfig()?.systemIcons;
    return this.error ? (
      <i part="error" class="progress-bar__icon">
        <slot name="error">
          <hbr-icon
            part="error-icon"
            asset={
              customSystemIcons?.["alerts-negative-large"] ||
              alertsNegativeLarge
            }
          />
        </slot>
      </i>
    ) : this.percentage === 100 ? (
      <i part="success" class="progress-bar__icon">
        <slot name="success">
          <hbr-icon
            part="success-icon"
            asset={
              customSystemIcons?.["alert-positive-large"] || alertsPositiveLarge
            }
          />
        </slot>
      </i>
    ) : this.indeterminate ? null : (
      <span class="progress-bar__value" part="percentage-text">
        <slot name="percentage">{this.percentage}%</slot>
      </span>
    );
  }

  handleSlotChange() {
    this.hasHelpTextSlot = hasSlot(this.host, "help-text");
    this.hasLabelSlot = hasSlot(this.host, "label");
    this.hasContent = hasSlot(this.host);
    this.hasFrontSlot = hasSlot(this.host, "front");
    this.hasRearSlot = hasSlot(this.host, "rear");
  }

  render() {
    const customSystemIcons = getBootstrapConfig()?.systemIcons;
    const isStop =
      !this.noncancelable &&
      this.percentage !== 100 &&
      !this.error &&
      !this.indeterminate;
    return (
      <Host>
        <FormControl
          inputId=""
          labelId={this.labelId}
          size={this.size}
          isRequired={this.required}
          hasLabelSlot={this.hasLabelSlot}
          hasFrontSlot={this.hasFrontSlot}
          hasRearSlot={this.hasRearSlot}
          hasHelpTextSlot={this.hasHelpTextSlot}
          label={this.label}
          helpText={this.helpText}
          helpTextId={this.helpTextId || this._helpTextId}
          hasError={this.error}
          isDisabled={this.disabled}
        >
          <div
            part="base"
            class={{
              "progress-bar": true,
              "progress-bar--success": this.percentage === 100,
              "progress-bar--indeterminate": this.indeterminate,
              "progress-bar--error": this.error,
              "progress-bar--stop": isStop,
              "progress-bar--suffix": !this.noSuffix,
              "progress-bar--label-without-suffix":
                this.noSuffix && this.label !== "",
              "progress-bar--inanimate": this.inanimate,
            }}
            role="progressbar"
            aria-valuemin="0"
            aria-valuemax="100"
            aria-valuenow={this.indeterminate ? null : this.percentage}
            tabIndex={this.disabled ? -1 : 0}
            aria-label={this.aria?.label}
            aria-labelledby={
              this.label ? this.labelId : this.aria?.labelledby || ""
            }
            aria-describedby={this.helpText ? this._helpTextId : ""}
          >
            <div class="progress-bar__track" part="track">
              <div
                part="percentage"
                class="progress-bar__percentage"
                style={{
                  width: `${this.percentage}%`,
                }}
              >
                {!this.indeterminate && (
                  <span part="label" class="progress-bar__label">
                    <slot />
                  </span>
                )}
              </div>
            </div>

            {!this.noSuffix && (
              <div part="suffix" class="progress-bar__suffix">
                <slot name="suffix">
                  {this.indicator && this.renderIndicator()}
                  {isStop && (
                    <i class="progress-bar__icon progress-bar__icon-stop">
                      <slot name="stop">
                        <hbr-icon-button
                          asset={customSystemIcons?.remove || remove}
                          arialabel="Stop progress"
                          onClick={(event) => this.hbrStop.emit({ event })}
                        />
                      </slot>
                    </i>
                  )}
                </slot>
              </div>
            )}
          </div>
        </FormControl>
      </Host>
    );
  }
}
